import os
import time
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import ClientError


class CognitoTokenRefresher:
    def __init__(
        self,
        client_id: Optional[str] = None,
        client_secret: Optional[str] = None,
        region_name: Optional[str] = None,
    ) -> None:
        self.client_id = client_id or os.environ.get("COGNITO_CLIENT_ID")
        self.client_secret = client_secret or os.environ.get("COGNITO_CLIENT_SECRET")
        self.region_name = region_name or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")

        if not self.client_id:
            raise ValueError("Missing Amazon Cognito app client id. Set COGNITO_CLIENT_ID.")
        if not self.region_name:
            raise ValueError("Missing AWS region. Set AWS_REGION or AWS_DEFAULT_REGION.")

        self.client = boto3.client("cognito-idp", region_name=self.region_name)

    def refresh_session(
        self,
        refresh_token: str,
        username: Optional[str] = None,
    ) -> Dict[str, Any]:
        if not refresh_token:
            raise ValueError("refresh_token is required")

        auth_parameters = {
            "REFRESH_TOKEN": refresh_token,
        }
        if self.client_secret:
            if not username:
                raise ValueError("username is required when the Cognito app client has a secret")
            auth_parameters["SECRET_HASH"] = self._secret_hash(username)

        try:
            response = self.client.initiate_auth(
                AuthFlow="REFRESH_TOKEN_AUTH",
                AuthParameters=auth_parameters,
                ClientId=self.client_id,
            )
        except ClientError as exc:
            raise RuntimeError(f"Failed to refresh Cognito session: {exc}") from exc

        result = response.get("AuthenticationResult", {})
        if not result:
            raise RuntimeError("Cognito returned no AuthenticationResult on refresh")

        expires_in = int(result.get("ExpiresIn", 0))
        expires_at = int(time.time()) + expires_in if expires_in else None

        normalized = {
            "access_token": result.get("AccessToken"),
            "id_token": result.get("IdToken"),
            "refresh_token": result.get("RefreshToken", refresh_token),
            "token_type": result.get("TokenType"),
            "expires_in": expires_in,
            "expires_at": expires_at,
        }
        return normalized

    def _secret_hash(self, username: str) -> str:
        import base64
        import hmac
        import hashlib

        message = username + self.client_id
        digest = hmac.new(
            self.client_secret.encode("utf-8"),
            message.encode("utf-8"),
            hashlib.sha256,
        ).digest()
        return base64.b64encode(digest).decode("utf-8")
